import sympy as sp

# Define the radius of the semicircles
r = 1
# Area of one full circle
full_circle = sp.pi * r**2
# Area of one semicircle
semicircle = full_circle / 2
# Area of the shaded region (1 full circle minus 3 semicircles minus overlapping part)
shaded_area = full_circle - 3 * semicircle - (1/2) * sp.pi
print(shaded_area.evalf())
